create or replace trigger apx_demo_user_roles_trg
before insert or update on apx_demo_user_roles
for each row
begin
   :new.username  := upper(:new.username);
   :new.role_code := upper(:new.role_code);
   if inserting then
      :new.created_by := apx_demo_sec_pkg.app_user;
      :new.created_on := sysdate;
   end if;
   :new.updated_by := apx_demo_sec_pkg.app_user;
   :new.updated_on := sysdate;
end;
/

