create or replace trigger apx_demo_requests_trg
before insert or update on apx_demo_requests
for each row
begin
   if inserting then
      if not apx_demo_approval_pkg.bypass then
         :new.status := 'DRAFT';
      end if;
      if :new.request_no is null then
         :new.request_no := apx_demo_doc_pkg.next_no('REQ');
      end if;
   elsif not apx_demo_approval_pkg.bypass then
      if :old.status = 'SUBMITTED' then
         raise_application_error(-20110, 'Permintaan Barang ' || :old.request_no || ' sedang menunggu approval dan tidak dapat diubah.');
      end if;
      if :old.status in ('CANCELLED', 'CLOSED') then
         raise_application_error(-20111, 'Permintaan Barang ' || :old.request_no || ' sudah ' || :old.status || '.');
      end if;
      if :new.status <> :old.status
         and not (:old.status in ('APPROVED', 'FULFILLED', 'CLOSED') and :new.status in ('FULFILLED', 'CLOSED'))
      then
         raise_application_error(-20112, 'Perubahan status ' || :old.status || ' -> ' || :new.status || ' tidak diizinkan. Gunakan Submit for Approval.');
      end if;
      -- kolom terkunci setelah approval (BR change management)
      if :old.status not in ('DRAFT', 'REJECTED') then
         :new.department_id := :old.department_id;
         :new.purpose := :old.purpose;
         :new.need_date := :old.need_date;
      end if;
   end if;
   if inserting then
      :new.created_by := apx_demo_sec_pkg.app_user;
      :new.created_on := sysdate;
   end if;
   :new.updated_by := apx_demo_sec_pkg.app_user;
   :new.updated_on := sysdate;
end;
/

create or replace trigger apx_demo_request_lines_trg
before insert or update or delete on apx_demo_request_lines
for each row
declare
   l_parent_status varchar2(30);
   e_mutating      exception;
   pragma exception_init(e_mutating, -4091);
begin
   begin
      select status
        into l_parent_status
        from apx_demo_requests
       where request_id = coalesce(:new.request_id, :old.request_id);
   exception
      when e_mutating then
         return; -- delete cascade dari apx_demo_requests
   end;
   if not apx_demo_approval_pkg.bypass and l_parent_status not in ('DRAFT', 'REJECTED') then
      raise_application_error(-20121, 'Baris Permintaan tidak dapat diubah karena Permintaan Barang berstatus ' || l_parent_status || '.');
   end if;
   if deleting then
      return;
   end if;
   if inserting then
      :new.created_by := apx_demo_sec_pkg.app_user;
      :new.created_on := sysdate;
   end if;
   :new.updated_by := apx_demo_sec_pkg.app_user;
   :new.updated_on := sysdate;
end;
/
